def outer():
 x=7
 def inner():
  if False: print(x)
  return eval("x")
 return inner
print(outer()())

def outer():
 x=7
 def inner(): return eval("x")
 return inner
try: outer()()
except NameError: print("not captured")

g={"x":7}
l={"x":9}
print(eval("x",g,l),eval("globals()",g,l) is g,eval("locals()",g,l) is l)
print(eval("x",g),eval("locals()",g) is g)

g={"x":7}
l={"x":9}
print(eval("x",globals=g,locals=l),eval("x",g,locals=l))

g={"x":7}
l={"x":9}
f=eval("lambda: x",g,l)
print(f(),f.__globals__ is g)
g["x"]=11
print(f())

g={"x":7}
f=eval("lambda a: (lambda: a+x)",g)(9)
print(f(),f.__closure__[0].cell_contents)

def f(): pass
g={}
print(eval("7",g),g["__builtins__"] is f.__builtins__)

b={"len":len}
g={"__builtins__":b}
print(eval("len([7,9])",g),g["__builtins__"] is b)
try: eval("open('file')",g)
except NameError: print("unavailable")

g={"__builtins__":{"len":len}}
f=eval("lambda: len([7,9])",g)
g["__builtins__"]={}
print(f())

g={}
try: eval("broken=",g)
except SyntaxError: print("syntax","__builtins__" in g)

g={}
try: eval(7,g)
except TypeError: print("type","__builtins__" in g)

class Mapping:
 def __getitem__(self,key):
  print("get",key)
  if key=="x": return 7
  raise KeyError(key)
print(eval("x+y",{"y":9},Mapping()))

class Mapping:
 def __getitem__(self,key):
  print("get",key)
  raise ValueError("mapping")
try: eval("x",{},Mapping())
except ValueError as e: print(str(e))

class Mapping:
 def __init__(self): self.data={}
 def __getitem__(self,key): return self.data[key]
 def __setitem__(self,key,value):
  print("set",key,value)
  self.data[key]=value
m=Mapping()
print(eval("(x:=7)",{},m),m.data["x"])

class D(dict):
 def __getitem__(self,key):
  print("get",key)
  return dict.__getitem__(self,key)
g=D()
dict.__setitem__(g,"x",7)
print(eval("x",g),eval("globals()",g) is g)

class D(dict):
 def __getitem__(self,key): raise ValueError("override")
 def __setitem__(self,key,value): raise ValueError("override")
g=D()
dict.__setitem__(g,"x",7)
f=eval("lambda: x",g,{})
print(f(),f.__globals__ is g,"__builtins__" in g)

class Mapping:
 def __getitem__(self,key):
  if key=="x": return 7
  raise KeyError(key)
g={"__builtins__":Mapping()}
print(eval("x",g))
try: eval("missing",g)
except NameError: print("missing")

def f(x): return x
try: eval(f.__code__,{}, {"x":7})
except UnboundLocalError: print("unbound")

def outer():
 x=7
 def f(): return x
 return f
g={}
try: eval(outer().__code__,g)
except TypeError: print("free","__builtins__" in g)

class D(dict):
 def __getitem__(self,key):
  print("builtin",key)
  return 7
print(eval("x",{"__builtins__":D()}))

class Mapping:
 def __init__(self): self.data={}
 def __getitem__(self,k): return self.data[k]
 def __setitem__(self,k,v): self.data[k]=v
class Meta(type):
 @classmethod
 def __prepare__(meta,name,bases): return Mapping()
 def __new__(meta,name,bases,ns): return ns
class Result(metaclass=Meta):
 x=7
 y=eval("x+9")
print(Result.data["y"])

class Mapping:
 def __getitem__(self,k): raise KeyError(k)
m=Mapping()
print(eval("locals()",{},m) is m)

def f(): return eval("len([7,9])",{})
f.__globals__["__builtins__"]={"eval":eval,"len":lambda x: 13}
# Defining builtins are captured when a function is created.
g=eval("lambda: eval('len([7,9])',{})", {"__builtins__":{"eval":eval,"len":lambda x: 13}})
print(g())
